  @fn nudgeSelected(direction)  @ 272-279
      @invariant  nudge steps one row, all-or-nothing; refused if any selected dest start is occupied.  @ 271
  @fn armedByCursor(takes)  @ 283-288
      -- The target whose start row the caret stands on, if any. That row is the one
      -- place the head is armed, and only that take's move carries the caret along.
  @fn moveHeads(takes, armed, direction)  @ 292-307
      -- The start edge walks and the end holds, so the rendered length moves the other way —
      -- floored at one row, since a take that renders nothing is gone from the grid undeleted.
  @fn moveTails(takes, direction)  @ 311-328
      -- Natural is measured from the source origin, so a head rides along and the
      -- edge that moves is the end.
  @fn resizeSelected(direction)  @ 332-338
      @invariant  caret on a target's start row moves the head, else the tail. See docs/arrangeView.md  @ 330
      @invariant  resize writes natural length (±1 bpr, floored 1 bpr); a head move floors the same way  @ 331
  @fn deleteSelected()  @ 340-347
  @fn diveSelected()  @ 351-359
